;const _e6811=WF.el("tr",{});const _e6812=WF.el("th",{scope:"col"},"Value");_e6811.appendChild(_e6812);const _e6813=WF.el("th",{scope:"col"},"Output");_e6811.appendChild(_e6813);_e6810.appendChild(_e6811);_e6809.appendChild(_e6810);const _e6814=WF.el("tbody",{});const _e6815=WF.el("tr",{});const _e6816=WF.el("td",{});const _e6817=WF.el("div",{className:"wf-markdown",markdown:"`human`"});_e6816.appendChild(_e6817);_e6815.appendChild(_e6816);const _e6818=WF.el("td",{},"Rendered findings on standard error.");_e6815.appendChild(_e6818);_e6814.appendChild(_e6815);const _e6819=WF.el("tr",{});const _e6820=WF.el("td",{});const _e6821=WF.el("div",{className:"wf-markdown",markdown:"`json`"});_e6820.appendChild(_e6821);_e6819.appendChild(_e6820);const _e6822=WF.el("td",{},"One document on standard output: every finding with its code, place, hint, related places and fixes, and the counts.");_e6819.appendChild(_e6822);_e6814.appendChild(_e6819);const _e6823=WF.el("tr",{});const _e6824=WF.el("td",{});const _e6825=WF.el("div",{className:"wf-markdown",markdown:"`sarif`"});_e6824.appendChild(_e6825);_e6823.appendChild(_e6824);const _e6826=WF.el("td",{},"SARIF 2.1.0, for GitHub code scanning and every other SARIF reader.");_e6823.appendChild(_e6826);_e6814.appendChild(_e6823);const _e6827=WF.el("tr",{});const _e6828=WF.el("td",{});const _e6829=WF.el("div",{className:"wf-markdown",markdown:"`github`"});_e6828.appendChild(_e6829);_e6827.appendChild(_e6828);const _e6830=WF.el("td",{});const _e6831=WF.el("div",{className:"wf-markdown",markdown:"`::error file=…` annotations on standard output, which a workflow shows on the pull request; the rendered findings stay on standard error."});_e6830.appendChild(_e6831);_e6827.appendChild(_e6830);_e6814.appendChild(_e6827);_e6809.appendChild(_e6814);_e6591.appendChild(_e6809);const _e6832=WF.el("div",{className:"wf-markdown",markdown:"With `json` or `sarif`, the build's progress goes to standard error, so standard output holds the document alone.\n\n`--cache` keeps what it renders in `.wf-cache/build/`. A page is taken from the cache when its inputs are unchanged: its own text, every component it reaches, and what every page reads — the shell, the stores, constants and data, every page's title and route, the config, the translations and the compiler. The output is byte for byte what a build without `--cache` writes. A build with nothing to reuse fills the cache, and each build keeps only the entries it used.\n\n`--studio` stamps every element's root with `data-wf-node`, its node id, which is the same in the pre-rendered page and the live one. An instance of one of the project's components also carries `data-wf-call`: the calls that made it, innermost first. `nodes.json`, written beside the site, maps each id to where it is written (file, bytes, line), what it calls, its parent, the loops and branches it is inside, and what its arguments read. A build without `--studio` stamps nothing and removes any `nodes.json` it finds.\n\n`--stats` prints every text file with its gzipped size and how much it changed since the last build, the runtime modules the build kept and what reached each one, and the design tokens it left out.\n\nSee also: [Diagnostics](/docs/guide/diagnostics), [Performance](/docs/guide/performance)."});_e6591.appendChild(_e6832);const _e6833=WF.el("h3",{className:"wf-heading",id:"wf-serve"},"wf serve");_e6591.appendChild(_e6833);const _e6834=WF.el("div",{className:"wf-markdown",markdown:"Runs the development server: it builds once, serves the output, and rebuilds and reloads on every save.\n\n**Usage:** `wf serve [OPTIONS]`"});_e6591.appendChild(_e6834);const _e6835=WF.el("table",{className:"wf-table"},WF.el("caption",{className:"wf-visually-hidden"},"wf serve"));const _e6836=WF.el("thead",{});const _e6837=WF.el("tr",{});const _e6838=WF.el("th",{scope:"col"},"Option");_e6837.appendChild(_e6838);const _e6839=WF.el("th",{scope:"col"},"Value");_e6837.appendChild(_e6839);const _e6840=WF.el("th",{scope:"col"},"Default");_e6837.appendChild(_e6840);const _e6841=WF.el("th",{scope:"col"},"Meaning");_e6837.appendChild(_e6841);_e6836.appendChild(_e6837);_e6835.appendChild(_e6836);const _e6842=WF.el("tbody",{});const _e6843=WF.el("tr",{});const _e6844=WF.el("td",{});const _e6845=WF.el("div",{className:"wf-markdown",markdown:"`-d`, `--dir`"});_e6844.appendChild(_e6845);_e6843.appendChild(_e6844);const _e6846=WF.el("td",{},"a directory");_e6843.appendChild(_e6846);const _e6847=WF.el("td",{});const _e6848=WF.el("div",{className:"wf-markdown",markdown:"`.`"});_e6847.appendChild(_e6848);_e6843.appendChild(_e6847);const _e6849=WF.el("td",{},"The project to serve.");_e6843.appendChild(_e6849);_e6842.appendChild(_e6843);const _e6850=WF.el("tr",{});const _e6851=WF.el("td",{});const _e6852=WF.el("div",{className:"wf-markdown",markdown:"`--host`"});_e6851.appendChild(_e6852);_e6850.appendChild(_e6851);const _e6853=WF.el("td",{},"an address");_e6850.appendChild(_e6853);const _e6854=WF.el("td",{});const _e6855=WF.el("div",{className:"wf-markdown",markdown:"`127.0.0.1`"});_e6854.appendChild(_e6855);_e6850.appendChild(_e6854);const _e6856=WF.el("td",{});const _e6857=WF.el("div",{className:"wf-markdown",markdown:"Where to listen: this machine only, unless told otherwise. `0.0.0.0` lets a phone on the same network reach it."});_e6856.appendChild(_e6857);_e6850.appendChild(_e6856);_e6842.appendChild(_e6850);const _e6858=WF.el("tr",{});const _e6859=WF.el("td",{});const _e6860=WF.el("div",{className:"wf-markdown",markdown:"`--allow-output-outside`"});_e6859.appendChild(_e6860);_e6858.appendChild(_e6859);const _e6861=WF.el("td",{},"—");_e6858.appendChild(_e6861);const _e6862=WF.el("td",{},"off");_e6858.appendChild(_e6862);const _e6863=WF.el("td",{});const _e6864=WF.el("div",{className:"wf-markdown",markdown:"Lets `build.output` name a directory outside the project."});_e6863.appendChild(_e6864);_e6858.appendChild(_e6863);_e6842.appendChild(_e6858);_e6835.appendChild(_e6842);_e6591.appendChild(_e6835);const _e6865=Component_Terminal({lines:[({command:"wf serve",output:""}),({command:"wf serve --host 0.0.0.0     # a phone on this network, at the address it prints",output:""})]});_e6591.appendChild(_e6865);const _e6866=WF.el("div",{className:"wf-markdown",markdown:"The server listens on `dev.port` (3000), on `127.0.0.1`: nothing else on the network can reach it unless `--host` says so. It watches `src/`, `public/` and the config, rebuilds on a change, and reloads every open tab. Each rebuild is a `wf build --cache`, so only the pages the change reached are rendered again.\n\nIt serves the build and nothing beside it: an address that climbs out (`/../`, written plainly or as `%2e%2e`), holds a backslash or a NUL, or reaches a link out of the build is a `404`. It answers only a request whose `Host` is a name it is reached by — `localhost`, an address written as numbers, the `--host` it was given, and with `--host 0.0.0.0` a `.local` name — so a page on another site cannot point a name of its own at this machine and read the build (DNS rebinding); any other gets a `421`. It answers several requests at once, streams files rather than reading them whole, and compresses a file once until it changes.\n\nWhen a build fails, the last good page stays up and the error is drawn over it — file, line, message and hint — until a save fixes it. The overlay is served at `/__wf/dev.js`, and the build's state, as JSON, at `/__wf/status`.\n\nEvery page the server sends also carries a **stores** button. It shows what each store holds, a log of every action with the state on each side of it, and lets you put a store back to before an action ran ([Stores](/docs/guide/stores#looking-at-one-while-it-runs)). The service worker of an offline site is removed under `wf serve`, so an edit is never hidden behind its cache.\n\nA request that is not a navigation — a `fetch`, a script, an image — for a file the build did not write gets a `404`, as a host would send, and a line in the terminal naming the file. Only a navigation gets the single-page shell. (Answering a missing API with the shell's HTML makes the page fail to parse it, far from the cause.)\n\nA build under `wf serve` is a *development build*, and it adds these checks to the running page:\n\n- A response with a declared type — `resource users: [User] = …`, an `api` endpoint's `-> User` — is held to that type as it arrives. One that does not match takes the `error` arm as a `.parse` error naming the place: `$[1].name is missing`.\n- A route no page answers (and no `path: \"*\"` page catches) shows a `404` box saying so. A deployed page shows nothing.\n- An item of a `for` that throws shows where it is and what it threw, and the rest of the list draws. On a deployed page the item leaves a gap and the console says why.\n- An effect that changes what it reads every time it runs is stopped after a hundred runs, with a warning, instead of overflowing the stack. A deployed page stops it too, silently.\n\nSee also: [`dev` in Configuration](/docs/guide/config#dev)."});_e6591.appendChild(_e6866);const _e6867=WF.el("h3",{className:"wf-heading",id:"wf-generate"},"wf generate");_e6591.appendChild(_e6867);const _e6868=WF.el("div",{className:"wf-markdown",markdown:"Writes a starter page, component or store.\n\n**Usage:** `wf generate [OPTIONS] KIND NAME`"});_e6591.appendChild(_e6868);const _e6869=WF.el("table",{className:"wf-table"},WF.el("caption",{className:"wf-visually-hidden"},"wf generate"));const _e6870=WF.el("thead",{});const _e6871=WF.el("tr",{});const _e6872=WF.el("th",{scope:"col"},"Option");_e6871.appendChild(_e6872);const _e6873=WF.el("th",{scope:"col"},"Value");_e6871.appendChild(_e6873);const _e6874=WF.el("th",{scope:"col"},"Default");_e6871.appendChild(_e6874);const _e6875=WF.el("th",{scope:"col"},"Meaning");_e6871.appendChild(_e6875);_e6870.appendChild(_e6871);_e6869.appendChild(_e6870);const _e6876=WF.el("tbody",{});const _e6877=WF.el("tr",{});const _e6878=WF.el("td",{});const _e6879